<template>
  <section class="module-page resource-management">
    <header class="page-heading"><div><h1>资源管理</h1><p>管理课程资源、公共资源、交换空间和作业空间容量。</p></div><el-button icon="el-icon-refresh" :loading="loading" @click="load">刷新</el-button></header>
    <el-tabs v-model="space" @tab-click="changeSpace"><el-tab-pane label="课程资源库" name="course" /><el-tab-pane label="公共资源库" name="public" /><el-tab-pane label="交换空间" name="exchange" /><el-tab-pane label="作业空间" name="homework" /></el-tabs>
    <section v-if="space === 'homework'" class="homework-summary"><div><small>作业空间文件</small><strong>{{ homeworkSummary.fileCount || 0 }}</strong><span>管理员不可查看文件明细</span></div><div><small>占用容量</small><strong>{{ formatSize(homeworkSummary.totalBytes) }}</strong><span>全部用户作业空间汇总</span></div><el-button type="danger" plain icon="el-icon-delete" @click="clearSpace('homework')">一键清空作业空间</el-button></section>
    <template v-else>
      <div v-if="space === 'exchange'" class="space-actions"><el-alert title="交换空间允许所有平台用户上传文件；管理员可以管理全部文件。" type="info" :closable="false" /><el-button type="danger" plain icon="el-icon-delete" @click="clearSpace('exchange')">一键清空交换空间</el-button></div>
      <ResourceBrowser :directories="entries.directories" :files="entries.files" :breadcrumbs="breadcrumbs" :loading="loading" :can-upload="true" :can-create-directory="true" :can-delete="true" :allow-deliver="space === 'course'" deliver-label="发送到所有已分配课程环境" @navigate="navigate" @open-directory="openDirectory" @create-directory="createDirectory" @upload="uploadVisible=true" @download="download" @deliver="deliver" @remove="remove" />
    </template>
    <ResourceUploadDialog :visible.sync="uploadVisible" :admin="true" :space="space" :directory-id="currentDirectoryId" :courses="courses" @uploaded="load" />
  </section>
</template>
<script>
import ResourceBrowser from '@/components/resources/ResourceBrowser.vue'
import ResourceUploadDialog from '@/components/resources/ResourceUploadDialog.vue'
import { listResourceEntries, createResourceDirectory, getResourceDownload, deleteResourceFile, deleteResourceDirectory, getHomeworkSummary, clearResourceSpace } from '@/api/ResourceSpaces'
import { listAdminCourses, deliverCourseResourceToAll } from '@/api/Courses'
export default {components:{ResourceBrowser,ResourceUploadDialog},data:()=>({space:'course',loading:false,entries:{directories:[],files:[]},breadcrumbs:[{name:'根目录',id:null}],uploadVisible:false,courses:[],homeworkSummary:{}}),computed:{currentDirectoryId(){return this.breadcrumbs[this.breadcrumbs.length-1].id}},created(){this.loadCourses();this.load()},methods:{async loadCourses(){const result=await listAdminCourses();this.courses=result.data||[]},async load(){this.loading=true;try{if(this.space==='homework'){const result=await getHomeworkSummary();this.homeworkSummary=result.data||{};return}const result=await listResourceEntries(true,this.space,this.currentDirectoryId);this.entries=result.data||{directories:[],files:[]}}finally{this.loading=false}},changeSpace(){this.breadcrumbs=[{name:'根目录',id:null}];this.entries={directories:[],files:[]};this.load()},navigate(item,index){this.breadcrumbs=this.breadcrumbs.slice(0,index+1);this.load()},openDirectory(item){this.breadcrumbs.push({name:item.name,id:item.directoryId});this.load()},async createDirectory(){const result=await this.$prompt('输入新目录名称','新建目录',{inputPattern:/^(?!\.{1,2}$)[^\\/]+$/,inputErrorMessage:'目录名称无效'});await createResourceDirectory(true,this.space,{parentId:this.currentDirectoryId,name:result.value});this.$message.success('目录已创建');await this.load()},async download(file){const result=await getResourceDownload(true,this.space,file.fileId);window.open(result.data.downloadUrl,'_blank','noopener')},async deliver(file){await this.$confirm(`确认将“${file.fileName}”发送到所有已分配该课程的实训环境？`,'批量发送',{type:'warning'});const records=(await deliverCourseResourceToAll(file.fileId)).data||[];const failed=records.filter(item=>item.state==='FAILED').length;this.$message[failed?'warning':'success'](`成功 ${records.length-failed} 个，失败 ${failed} 个`)},async remove(item){await this.$confirm(`确认删除“${item.name||item.fileName}”？`,'删除确认',{type:'warning'});if(item.kind==='directory')await deleteResourceDirectory(true,this.space,item.directoryId);else await deleteResourceFile(true,this.space,item.fileId);this.$message.success('已删除');await this.load()},async clearSpace(space){const summary=space==='homework'?this.homeworkSummary:null;await this.$confirm(`将清空${space==='homework'?'全部用户作业空间':'交换空间'}${summary?`（${summary.fileCount||0} 个文件）`:''}，此操作不可恢复。`,'一键清空',{type:'error',confirmButtonText:'确认清空'});await clearResourceSpace(space);this.$message.success('空间已清空');await this.load()},formatSize(bytes){if(!bytes)return'0 B';const units=['B','KB','MB','GB','TB'];let value=Number(bytes),index=0;while(value>=1024&&index<4){value/=1024;index++}return `${value<10&&index?value.toFixed(1):Math.round(value)} ${units[index]}`}}}
</script>
<style scoped>.resource-management{width:100%}.page-heading,.space-actions,.homework-summary{display:flex;align-items:flex-start;justify-content:space-between;gap:14px}.page-heading{margin-bottom:14px}.page-heading h1{margin:0;font-size:28px}.page-heading p{margin:6px 0 0;color:var(--ui-muted);font-size:13px}.space-actions{align-items:center;margin-bottom:12px}.space-actions .el-alert{flex:1}.homework-summary{align-items:center;padding:24px;background:#fff;border:1px solid var(--ui-border);border-radius:8px}.homework-summary>div{min-width:180px}.homework-summary small,.homework-summary span{display:block;color:var(--ui-muted);font-size:12px}.homework-summary strong{display:block;margin:8px 0;font-size:28px}@media(max-width:700px){.page-heading,.space-actions,.homework-summary{align-items:stretch;flex-direction:column}}</style>
